import { useEffect, useState } from "react";

type StoredValue<T> = {
  key: string;
  value: T;
  shouldPersist: boolean;
};

function readStoredValue<T>(key: string, initialValue: T): StoredValue<T> {
  if (typeof window === "undefined") {
    return { key, value: initialValue, shouldPersist: false };
  }

  try {
    const raw = window.localStorage.getItem(key);
    if (raw === null) return { key, value: initialValue, shouldPersist: true };
    return { key, value: JSON.parse(raw) as T, shouldPersist: false };
  } catch {
    // Do not overwrite malformed or inaccessible storage automatically.
    return { key, value: initialValue, shouldPersist: false };
  }
}

function useLocalStorage<T>(key: string, initialValue: T) {
  const [stored, setStored] = useState(() => readStoredValue(key, initialValue));
  const value = stored.key === key
    ? stored.value
    : readStoredValue(key, initialValue).value;

  useEffect(() => {
    if (stored.key !== key) {
      setStored(readStoredValue(key, initialValue));
      return;
    }
    if (!stored.shouldPersist || typeof window === "undefined") return;

    try {
      const serialized = JSON.stringify(stored.value);
      if (serialized !== undefined) window.localStorage.setItem(key, serialized);
    } catch {
      // Keep in-memory state usable when storage is blocked or full.
    }
  }, [key, initialValue, stored]);

  function setValue(next: T | ((current: T) => T)) {
    setStored((current) => {
      const previous = current.key === key
        ? current.value
        : readStoredValue(key, initialValue).value;
      const value = typeof next === "function"
        ? (next as (current: T) => T)(previous)
        : next;
      return { key, value, shouldPersist: true };
    });
  }

  return [value, setValue] as const;
}

